//! The 0.1 library import (M10) drawn offscreen: screenshots of the gate,
//! the progress, the summary, the bookshelf after it and a failure, light
//! and dark, into `<modules dir>/m10/`.
//!
//! GPUI runs headless (its test platform with the real macOS text system
//! and Metal drawing into a texture): nothing opens on screen. The new
//! library is a temporary, empty one, opened as the app opens it. The 0.1
//! libraries are P0-E's synthetic fixtures (m10-import.md 「测试数据」:
//! `sample` and `sample-stale`, generated by
//! `src/renderer/services/v2-handoff/m10-fixtures.test.ts`), laid out as the
//! 0.1 app keeps a library (`databases/drifting-library.db` and `assets/`)
//! in a temporary folder. Nothing reads an author's library.
//!
//! The progress shot holds one report still: a real one, recorded while
//! importing `sample` into a scratch library (the import is too quick to
//! catch halfway).
//!
//! ```text
//! cargo run -p dr-view-import --features capture --example import-capture -- \
//!     --fixtures <P0-E fixtures dir> --capture ../docs/rust-rewrite/modules
//! ```

use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::{Duration, Instant};

use anyhow::{Context as _, Result, bail};
use dr_import_v1::progress::{Progress, Step};
use dr_shell::{Services, SettingsFile, ShellInfo, Workspace};
use dr_ui::{Appearance, theme};
use dr_view_import::{LegacyImport, Running, State};
use dr_view_shelf::Shelf;
use gpui::{AnyWindowHandle, AppContext as _, Entity, HeadlessAppContext, px, size};

const W: f32 = 1280.0;
const H: f32 = 800.0;
const VERSION: &str = "0.2.0-dev";

/// A P0-E fixture as the 0.1 app keeps a library: `<dir>/<name>/databases/
/// drifting-library.db` and `<dir>/<name>/assets/`.
fn lay_out(fixtures: &Path, name: &str, dir: &Path) -> Result<PathBuf> {
    let root = dir.join(name);
    let databases = root.join("databases");
    std::fs::create_dir_all(&databases)?;
    std::fs::copy(
        fixtures.join(name).join("drifting-library.db"),
        databases.join("drifting-library.db"),
    )
    .with_context(|| format!("{name}: the fixture's database"))?;
    copy_dir(
        &fixtures.join(name).join("app-local-data").join("assets"),
        &root.join("assets"),
    )?;
    Ok(root)
}

fn copy_dir(from: &Path, to: &Path) -> Result<()> {
    if !from.is_dir() {
        return Ok(());
    }
    std::fs::create_dir_all(to)?;
    for entry in std::fs::read_dir(from)? {
        let entry = entry?;
        let target = to.join(entry.file_name());
        if entry.file_type()?.is_dir() {
            copy_dir(&entry.path(), &target)?;
        } else {
            std::fs::copy(entry.path(), target)?;
        }
    }
    Ok(())
}

/// One report from the middle of a real import of `root` (the second book's
/// bodies, about halfway), into a scratch library.
fn recorded_report(root: &Path) -> Result<Progress> {
    let scratch = tempfile::tempdir()?;
    let picked = dr_import_v1::locate::resolve(root)?;
    let mut options = dr_import_v1::run::Options::new(VERSION);
    options.old_root = Some(picked.root.clone());
    options.accept = dr_import_v1::gate::Accept::EVERYTHING;
    options.index = false;
    let mut reports = Vec::new();
    dr_import_v1::run::import_with(
        &picked.database,
        &scratch.path().join("library"),
        &options,
        &mut |p| reports.push(p.clone()),
    )?;
    let in_bodies: Vec<&Progress> = reports
        .iter()
        .filter(|p| p.step == Step::Bodies && p.book == p.books)
        .collect();
    in_bodies
        .get(in_bodies.len() / 2)
        .map(|p| (*p).clone())
        .context("no report from the last book's bodies")
}

struct Headless {
    cx: HeadlessAppContext,
    window: AnyWindowHandle,
    view: Entity<Workspace>,
    _library: tempfile::TempDir,
}

impl Headless {
    fn new(appearance: Appearance, locale: &str) -> Result<Headless> {
        let text_system = gpui_platform::current_platform(true).text_system();
        let mut cx = HeadlessAppContext::with_platform(
            text_system,
            Arc::new(dr_ui::Assets::new()),
            gpui_platform::current_headless_renderer,
        );
        // F3 and the import run on their own threads.
        cx.allow_parking();
        let dir = tempfile::tempdir()?;
        let library = dr_workspace::Workspace::open_dir(dir.path().join("library"), VERSION)?;
        cx.update(|cx| -> Result<()> {
            dr_ui::init(cx)?;
            let info = ShellInfo {
                app_name: "Drifting Next",
                bundle_id: "cc.drifting.next.dev",
                version: VERSION,
                url_scheme: "drifting-next-dev",
                forced_appearance: Some(appearance),
            };
            let mut file = SettingsFile::in_memory();
            file.set(dr_shell::settings::registry::UI_LOCALE, locale.into(), None)
                .ok();
            let services = Services {
                library: Some(library),
                ..Services::default()
            };
            dr_shell::init(info, services, file, cx);
            dr_view_shelf::init(cx);
            dr_view_import::init(cx);
            theme::force_appearance(Some(appearance), cx);
            Ok(())
        })?;
        let window = cx.open_window(size(px(W), px(H)), |window, cx| {
            cx.new(|cx| Workspace::new(window, cx))
        })?;
        let view = window.entity(&cx)?;
        let mut h = Headless {
            cx,
            window: window.into(),
            view,
            _library: dir,
        };
        h.wait(|h| h.shelf_read())?;
        h.settle()?;
        Ok(h)
    }

    fn shelf(&mut self) -> Entity<Shelf> {
        let view = self.view.clone();
        self.cx
            .update(|cx| view.read(cx).shelf.clone())
            .expect("the bookshelf")
            .view
            .downcast::<Shelf>()
            .expect("dr-view-shelf")
    }

    fn shelf_read(&mut self) -> bool {
        let shelf = self.shelf();
        self.cx.update(|cx| shelf.read(cx).data.is_some())
    }

    fn shelf_books(&mut self) -> usize {
        let shelf = self.shelf();
        self.cx
            .update(|cx| shelf.read(cx).data.as_ref().map_or(0, |d| d.books.len()))
    }

    fn import(&mut self) -> Entity<LegacyImport> {
        self.cx
            .update(|cx| dr_view_import::importer(cx))
            .expect("dr-view-import")
    }

    fn state(&mut self) -> State {
        let import = self.import();
        self.cx.update(|cx| import.read(cx).state().clone())
    }

    fn on_import(
        &mut self,
        f: impl FnOnce(&mut LegacyImport, &mut gpui::Window, &mut gpui::Context<LegacyImport>),
    ) {
        let import = self.import();
        self.cx
            .update_window(self.window, |_, window, cx| {
                import.update(cx, |i, cx| f(i, window, cx))
            })
            .ok();
    }

    fn draw(&mut self) -> Result<()> {
        let view = self.view.clone();
        self.cx.update_window(self.window, |_, window, cx| {
            window.simulate_next_frame(cx);
            view.update(cx, |_, cx| cx.notify());
            window.draw(cx).clear(cx);
        })
    }

    /// Runs until `done` holds (the import and F3 answer in their own time).
    fn wait(&mut self, done: impl Fn(&mut Headless) -> bool) -> Result<()> {
        let deadline = Instant::now() + Duration::from_secs(60);
        loop {
            self.draw()?;
            self.cx.run_until_parked();
            if done(self) {
                return Ok(());
            }
            if Instant::now() > deadline {
                bail!("timed out");
            }
            std::thread::sleep(Duration::from_millis(2));
        }
    }

    /// Draws for a little over the longest motion, so nothing is caught
    /// halfway.
    fn settle(&mut self) -> Result<()> {
        let started = Instant::now();
        while started.elapsed() < Duration::from_millis(600) {
            self.draw()?;
            self.cx.run_until_parked();
            std::thread::sleep(Duration::from_millis(16));
        }
        Ok(())
    }

    fn settled(&mut self) -> Result<State> {
        self.wait(|h| !matches!(h.state(), State::Running(_) | State::Picking))?;
        self.settle()?;
        Ok(self.state())
    }

    /// Writes the window as a 256-colour PNG (as the other captures do).
    fn save(&mut self, dir: &Path, name: &str) -> Result<()> {
        let image = self.cx.capture_screenshot(self.window)?;
        let (w, h) = image.dimensions();
        let rgba = image.into_raw();
        let quant = color_quant::NeuQuant::new(10, 256, &rgba);
        let indices: Vec<u8> = rgba
            .as_chunks::<4>()
            .0
            .iter()
            .map(|px| quant.index_of(px) as u8)
            .collect();
        let palette: Vec<u8> = quant
            .color_map_rgba()
            .as_chunks::<4>()
            .0
            .iter()
            .flat_map(|c| [c[0], c[1], c[2]])
            .collect();
        std::fs::create_dir_all(dir)?;
        let file = std::io::BufWriter::new(std::fs::File::create(dir.join(name))?);
        let mut encoder = png::Encoder::new(file, w, h);
        encoder.set_color(png::ColorType::Indexed);
        encoder.set_depth(png::BitDepth::Eight);
        encoder.set_palette(palette);
        encoder.set_compression(png::Compression::High);
        encoder.write_header()?.write_image_data(&indices)?;
        println!("wrote {}", dir.join(name).display());
        Ok(())
    }
}

fn capture(fixtures: PathBuf, modules: PathBuf) -> Result<()> {
    let out = modules.join("m10");
    let old = tempfile::tempdir()?;
    let sample = lay_out(&fixtures, "sample", old.path())?;
    let stale = lay_out(&fixtures, "sample-stale", old.path())?;
    let report = recorded_report(&sample)?;
    let nothing = old.path().join("empty-folder");
    std::fs::create_dir_all(&nothing)?;
    // A 0.1 data folder as the app finds it: `sample-stale` is its `legacy`
    // library, `sample` its `local` one.
    let base = old.path().join("cc.drifting.client");
    copy_dir(&stale, &base)?;
    copy_dir(&sample, &base.join("libraries").join("local"))?;
    std::fs::write(
        base.join("libraries.json"),
        r#"{"version":1,"active":"local","libraries":{"legacy":{"owner":{"kind":"local"}},"local":{"owner":{"kind":"local"}}}}"#,
    )?;

    for (appearance, suffix) in [(Appearance::Light, "light"), (Appearance::Dark, "dark")] {
        let mut h = Headless::new(appearance, "zh-CN")?;

        // The local 0.1 libraries, to pick from.
        let dir = base.clone();
        h.on_import(move |i, window, cx| {
            i.look_in(Some(dir));
            i.choose(window, cx);
        });
        h.settle()?;
        let State::Found(_) = h.state() else {
            bail!("the 0.1 libraries were not listed: {:?}", h.state());
        };
        h.save(&out, &format!("import-list-{suffix}.png"))?;
        h.on_import(|i, window, cx| i.close(window, cx));

        // The gate: the library without the handoff.
        let folder = stale.clone();
        h.on_import(move |i, window, cx| i.start(folder, window, cx));
        let State::Blocked(_) = h.settled()? else {
            bail!("sample-stale was not stopped: {:?}", h.state());
        };
        h.save(&out, &format!("import-gate-{suffix}.png"))?;

        // 「仍然导入」, and the summary.
        h.on_import(|i, window, cx| i.import_anyway(window, cx));
        let State::Done(done) = h.settled()? else {
            bail!("sample-stale was not imported: {:?}", h.state());
        };
        h.save(&out, &format!("import-done-{suffix}.png"))?;

        // The bookshelf with the new books.
        h.on_import(|i, window, cx| i.close(window, cx));
        let books = done.books.len();
        h.wait(|h| h.shelf_books() == books)?;
        h.settle()?;
        h.save(&out, &format!("import-shelf-{suffix}.png"))?;

        // The progress, held still at a recorded report.
        let running = |cancelling| {
            State::Running(Running {
                folder: "sample".into(),
                accept: dr_import_v1::gate::Accept::NOTHING,
                progress: Some(report.clone()),
                cancelling,
            })
        };
        let state = running(false);
        h.on_import(move |i, window, cx| i.show(state, window, cx));
        h.settle()?;
        h.save(&out, &format!("import-progress-{suffix}.png"))?;
        // 「取消」 pressed: the book is finished first.
        let state = running(true);
        h.on_import(move |i, window, cx| i.show(state, window, cx));
        h.settle()?;
        h.save(&out, &format!("import-stopping-{suffix}.png"))?;
        h.on_import(|i, window, cx| i.show(State::Idle, window, cx));

        // A folder without a 0.1 library.
        let folder = nothing.clone();
        h.on_import(move |i, window, cx| i.start(folder, window, cx));
        let State::Failed(_) = h.settled()? else {
            bail!("the empty folder did not fail: {:?}", h.state());
        };
        h.save(&out, &format!("import-failed-{suffix}.png"))?;
    }

    // The gate in English: longer kind labels stay on one line.
    let mut h = Headless::new(Appearance::Light, "en")?;
    let folder = stale.clone();
    h.on_import(move |i, window, cx| i.start(folder, window, cx));
    let State::Blocked(_) = h.settled()? else {
        bail!("sample-stale was not stopped: {:?}", h.state());
    };
    h.save(&out, "import-gate-en-light.png")?;
    Ok(())
}

fn main() -> Result<()> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    match args.as_slice() {
        [f, fixtures, c, modules] if f == "--fixtures" && c == "--capture" => {
            capture(PathBuf::from(fixtures), PathBuf::from(modules))
        }
        _ => bail!("usage: import-capture --fixtures <P0-E fixtures dir> --capture <modules dir>"),
    }
}
